"""Create private group/admin keys to embed when USB-flashing every group member."""
import argparse
import hashlib
import json
import os
from pathlib import Path
import secrets


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--import-credentials", type=Path, help="Reuse an existing group's private credentials JSON")
    parser.add_argument("--output-dir", type=Path, default=Path(__file__).resolve().parent)
    parser.add_argument("--rotate", action="store_true", help="Replace existing keys; all members must then be reflashed")
    args = parser.parse_args()
    directory = args.output_dir
    directory.mkdir(parents=True, exist_ok=True)
    paths = [directory / "group_keys.h", directory / "private_credentials.json"]
    if any(path.exists() for path in paths) and not args.rotate:
        parser.error("Keys already exist. Reuse them, or explicitly use --rotate.")
    keys = json.loads(args.import_credentials.read_text()) if args.import_credentials else {
        "groupKey": secrets.token_hex(32), "adminKey": secrets.token_hex(32)
    }
    for name in ("groupKey", "adminKey"):
        if not isinstance(keys.get(name), str) or len(keys[name]) != 64:
            parser.error(f"{name} must contain exactly 64 hexadecimal characters")
        try:
            material = bytes.fromhex(keys[name])
        except ValueError:
            parser.error(f"Invalid {name}")
        if not any(material):
            parser.error(f"{name} must not be all zeros")
    if keys["groupKey"] == keys["adminKey"]:
        parser.error("Group and administrator keys must be independent")
    header = "#pragma once\n// Private provisioning material. Do not commit or distribute publicly.\n"
    for field, symbol in (("groupKey", "INTER_COMMS_GROUP_KEY"), ("adminKey", "INTER_COMMS_ADMIN_KEY")):
        values = ", ".join(f"0x{value:02x}" for value in bytes.fromhex(keys[field]))
        header += f"static const uint8_t {symbol}[32] = {{{values}}};\n"
    profile = b"INTERCOMMS-V1:::" + hashlib.sha256(b"inter_comms/profile/v1" + bytes.fromhex(keys["groupKey"]) + bytes.fromhex(keys["adminKey"])).digest()
    assert len(profile) == 48
    header += "static const uint8_t INTER_COMMS_IMAGE_ID[48] = {" + ", ".join(f"0x{value:02x}" for value in profile) + "};\n"
    for path, content in zip(paths, (header, json.dumps(keys, indent=2) + "\n")):
        descriptor = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
        os.fchmod(descriptor, 0o600)
        with os.fdopen(descriptor, "w") as output:
            output.write(content)
    print("Private provisioning files written. Flash the same keyed firmware over USB to each group member.")
    print("The dashboard needs no login. Private group/profile material was not printed.")


if __name__ == "__main__":
    main()
# AI: end
